+          linear-gradient(135deg, #fbfcff 0%, var(--background) 100%);
+      }
+
+      main {
+        display: grid;
+        min-height: 100vh;
+        place-items: center;
+        padding: 2rem;
+      }
+
+      .support-card {
+        width: min(100%, 42rem);
+        padding: clamp(1.5rem, 4vw, 3rem);
+        border: 1px solid rgba(217, 224, 234, 0.9);
+        border-radius: 1.5rem;
+        background: rgba(255, 255, 255, 0.94);
+        box-shadow: 0 1.5rem 4rem rgba(23, 32, 51, 0.12);
+      }
+
+      .eyebrow {
+        margin: 0 0 0.75rem;
+        color: var(--primary);
+        font-size: 0.82rem;
+        font-weight: 800;
+        letter-spacing: 0.1em;
+        text-transform: uppercase;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2rem, 6vw, 3.35rem);
+        line-height: 1.05;
+        letter-spacing: -0.05em;
+      }
+
+      .intro {
+        max-width: 34rem;
+        margin: 1rem 0 2rem;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.6;
+      }
+
+      form {
+        display: grid;
+        gap: 1.15rem;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 0.5rem;
+      }
+
+      label {
+        font-size: 0.95rem;
+        font-weight: 750;
+      }
+
+      input {
+        width: 100%;
+        border: 1px solid var(--border);
+        border-radius: 0.9rem;
+        padding: 0.95rem 1rem;
+        color: var(--text);
+        background: #fff;
+        font: inherit;
+        transition:
+          border-color 160ms ease,
+          box-shadow 160ms ease,
+          transform 160ms ease;
+      }
+
+      input::placeholder {
+        color: #98a2b3;
+      }
+
+      input:focus {
+        border-color: var(--primary);
+        box-shadow: 0 0 0 0.25rem var(--ring);
+        outline: none;
+      }
+
+      input:user-invalid {
+        border-color: var(--error);
+      }
+
+      .helper-text {
+        margin: 0;
+        color: var(--muted);
+        font-size: 0.9rem;
+        line-height: 1.4;
+      }
+
+      button {
+        width: 100%;
+        margin-top: 0.35rem;
+        border: 0;
+        border-radius: 999px;
+        padding: 1rem 1.25rem;
+        color: #fff;
+        background: var(--primary);
+        box-shadow: 0 1rem 2rem rgba(54, 92, 255, 0.24);
+        cursor: pointer;
+        font: inherit;
+        font-weight: 800;
+        transition:
+          background 160ms ease,
+          transform 160ms ease,
+          box-shadow 160ms ease;
+      }
+
+      button:hover {
+        background: var(--primary-dark);
+        transform: translateY(-1px);
+        box-shadow: 0 1.2rem 2.25rem rgba(54, 92, 255, 0.3);
+      }
+
+      button:focus {
+        box-shadow:
+          0 0 0 0.25rem var(--ring),
+          0 1rem 2rem rgba(54, 92, 255, 0.24);
+        outline: none;
+      }
+
+      .form-status {
+        min-height: 1.5rem;
+        margin: 0.25rem 0 0;
+        font-size: 0.95rem;
+        font-weight: 700;
+      }
+
+      .form-status.success {
+        color: var(--success);
+      }
+
+      .form-status.error {
+        color: var(--error);
+      }
+
+      @media (max-width: 38rem) {
+        main {
+          padding: 1rem;
+        }
+
+        .support-card {
+          border-radius: 1.1rem;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main>
+      <section class="support-card" aria-labelledby="support-title">
+        <p class="eyebrow">Support</p>
+        <h1 id="support-title">How can we help?</h1>
+        <p class="intro">
+          Send a note to our support team and we will follow up with the best next
+          steps for your request.
+        </p>
+
+        <form id="support-form" action="#" method="post" novalidate>
+          <div class="form-field">
+            <label for="full-name">Full name</label>
+            <input
+              id="full-name"
+              name="fullName"
+              type="text"
+              autocomplete="name"
+              placeholder="Ada Lovelace"
+              required
+            >
+          </div>
+
+          <div class="form-field">
+            <label for="email">Email address</label>
+            <input
+              id="email"
+              name="email"
+              type="email"
+              autocomplete="email"
+              placeholder="ada@example.com"
+              required
+            >
+          </div>
+
+          <div class="form-field">
+            <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
+            <input
+              id="phone"
+              name="phone"
+              type="tel"
+              autocomplete="tel"
+              inputmode="tel"
+              aria-describedby="phone-helper"
+              placeholder="+1 555 123 4567"
+            >
+            <p class="helper-text" id="phone-helper">
+              Use country code, area code, and number, for example +1 555 123 4567.
+            </p>
+          </div>
+
+          <button type="submit">Contact support</button>
+          <p class="form-status" id="form-status" role="status" aria-live="polite"></p>
+        </form>
+      </section>
+    </main>
+
+    <script>
+      const form = document.querySelector("#support-form");
+      const status = document.querySelector("#form-status");
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+
+        if (!form.checkValidity()) {
+          status.textContent = "Please complete the required fields before submitting.";
+          status.className = "form-status error";
+          form.reportValidity();
+          return;
+        }
+
+        status.textContent = "Thanks. Your support request is ready to send.";
+        status.className = "form-status success";
+        form.reset();
+      });
+    </script>
+  </body>
+</html>
*** End Patch
