        --background: #f5f7fb;
        --card: #ffffff;
        --text: #172033;
        --muted: #667085;
        --border: #d9e0ea;
        --primary: #365cff;
        --primary-dark: #2445d8;
        --ring: rgba(54, 92, 255, 0.24);
        --success: #067647;
        --error: #b42318;
