        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(54, 92, 255, 0.16), transparent 34rem),
          linear-gradient(135deg, #fbfcff 0%, var(--background) 100%);
      }

